//! `Router::set_route_inside_parent_shapes()`, which the port takes from the
//! Adaptagrams fork that libavoid-js builds on (Aksem/adaptagrams), against
//! the C++ (golden: `tests/nested_shapes/golden.txt`, regenerated by
//! `tools/oracle/nested_shapes.sh`).
//!
//! Every scene has shapes nested inside other shapes.  With the option off,
//! the routes after every transaction must match upstream exactly; with it
//! on, they must match upstream with the fork's change applied
//! (`tools/oracle/nested_shapes.patch`).

mod scene_replay;

#[test]
fn nested_shapes_match_cpp() {
    let golden = include_str!("nested_shapes/golden.txt");
    let (checked, affected) = scene_replay::check_off_on(golden, |r, on| r.set_route_inside_parent_shapes(on));
    // The option must change routes in a good share of the scenes checked.
    assert!(affected * 2 > checked, "the option changes only {affected} of {checked} scenes");
}
